import Model from 'flarum/common/Model';
export default class CoAuthor extends Model {
  status() {
    return Model.attribute('status').call(this);
  }
  createdAt() {
    return Model.attribute('createdAt', Model.transformDate).call(this);
  }
  respondedAt() {
    return Model.attribute('respondedAt', Model.transformDate).call(this);
  }
  user() {
    return Model.hasOne('user').call(this);
  }
  discussion() {
    return Model.hasOne('discussion').call(this);
  }
  addedBy() {
    return Model.hasOne('addedBy').call(this);
  }
  apiEndpoint() {
    return '/co_authors' + (this.exists ? '/' + this.data.id : '');
  }
}
flarum.reg.add('tapao-co-authors', 'common/models/CoAuthor', CoAuthor);